VALUES ('306d1510-1237-58b3-ad85-756ed8c4c984', 'afe5eb5d-e4a1-505c-a07f-9a03c537fba1', 'cf278492-196c-58d5-bbda-7b91d3d92e44', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Display Name', 'The business-facing name by which the party is normally displayed and recognized. Provides a consistent human-readable representation independent of whether the party is a person or organization. Used in forms, search results, documents, transactions, reports, notifications, and user interfaces. It is a presentation identity for the Party and does not replace legal names, person names, or organization registration names stored by specializations. Required so every party can be unambiguously presented to users and business processes. Required — the record cannot be saved while this is empty. Up to 300 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
