VALUES ('7f5e894d-de38-5ffc-8697-638a0e4aebd4', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', '5727a8bf-884f-5446-92e1-7bcf0224305f', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Name', 'Common organizational name used in business operations. Used in search, forms, reports, documents, and transactions. LegalName may differ and provides formal legal identity. Provides human-readable organizational identification. Required for operational recognition. Required — the record cannot be saved while this is empty. Up to 200 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd65ee4a-0f75-5dfc-a378-b2c6c3b433f5', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'a9f0371a-fa5c-5272-9600-50494fd4844c', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Organization Type', 'Classifies the organizational structure represented by the specialization. Used for hierarchy, authorization, reporting, transaction scope, and organizational configuration. Organization type describes structure, not commercial role. Customer/Supplier behavior belongs to PartyRole specializations. Controls applicable organizational hierarchy and operating-context rules. Required for organizational interpretation. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dd3449de-ecab-58b4-8743-3ed6ec3f19b8', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'c12a0561-e9ce-5c25-9719-332131fed746', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Status', 'Lifecycle of the organizational specialization. Controls whether the organization can normally be selected as an organizational context. Organization status does not replace Party.status or PartyRole.status; all applicable states must permit new activity. Governs organizational use while preserving historical relationships. Required for eligibility checks. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cab27cd6-cc23-5486-b399-5b151459488d', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', '30afafe7-52a5-56a8-a223-4367f419d716', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Legal Name', 'Formal legal name of the organization. Used for contracts, invoices, tax, regulatory reporting, and legal documentation. LegalName is distinct from the operational name. Supplies legal presentation and compliance context. Optional when the organization is not a legal entity or the information is not yet known. Up to 300 characters.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a6d71811-7253-574c-bd52-2fea3caf247f', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'cb871b8f-49ed-52b1-bddd-1506c9646884', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Registration Number', 'Registration identifier assigned by a competent authority. Used for legal verification, compliance, tax, and integrations. Registration number identifies the organization in an external legal system, not in CEDM. Supports identity verification and compliance controls. Optional for organizational units without separate registration. Up to 100 characters.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ccdbd5e6-a978-5a24-9c86-592ac7917232', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'ddc2c4bd-0bf5-5b60-b3fe-b6da6df906b1', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Tax Identifier', 'Tax identifier applicable to the organization in a relevant jurisdiction. Used for tax determination, invoices, reporting, and compliance. Tax identity may vary by jurisdiction and should not replace Party identity. Supports tax-rule applicability and statutory reporting. Optional when no tax identifier applies or is known. Up to 100 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c54042c4-4d1f-530d-9a9c-bc448c3b228d', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'f5c1e737-6b2f-5d3f-b818-6f89ea66b1b0', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Party Type', 'Identifies whether the party is a person or an organization. Determines which party specialization is applicable and prevents business processes from interpreting an organization as an individual or vice versa. Used to select Person or Organization details and to drive validation, forms, search, reporting, and role assignment. PERSON requires the Person specialization; ORGANIZATION requires the Organization specialization. The party represents an individual human being. The party represents a legal, commercial, governmental, nonprofit, or other organized body. Required because the party''s specialization and applicable business semantics depend on it. Required — the record cannot be saved while this is empty.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('69ca6871-ee8b-527d-ac85-0d0e36941bea', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', '71da02e7-a786-52fa-91f3-e2e7716f3c48', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Display Name', 'The business-facing name by which the party is normally displayed and recognized. Provides a consistent human-readable representation independent of whether the party is a person or organization. Used in forms, search results, documents, transactions, reports, notifications, and user interfaces. It is a presentation identity for the Party and does not replace legal names, person names, or organization registration names stored by specializations. Required so every party can be unambiguously presented to users and business processes. Required — the record cannot be saved while this is empty. Up to 300 characters.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6bd393fb-7ad7-5190-905c-f6b4d89e37a4', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'abac3c08-3c41-57e1-82da-b6a9996a9042', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'External Reference', 'An identifier assigned to the party by an external system or business partner. Preserves a cross-system identity that allows CEDM to reconcile a party with another master-data system. Used for integrations, migration, reconciliation, EDI, synchronization, and external lookup. It is not the canonical CEDM identity; Party.partyId remains the internal identity while externalReference provides interoperability context. Optional when no external system identity exists or when the external identity is maintained elsewhere. Up to 200 characters.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c15d4f1c-5610-5b21-8e77-2c955d2a8490', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', 'f23214e8-fef3-5326-ad88-b7c374c57d0a', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Person', 'The Person this Organization belongs to.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
