INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6cdcc94c-9b58-5d1d-957a-2c2d55231b05', '3934e990-5ef3-5608-a2f6-fe6f87fdcb7f', '8e35e960-ac73-54fc-8e62-d5448416aacc', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Parent Organization', 'Immediate parent organizational unit. Supports enterprise hierarchy and organizational scope. Zero or one immediate parent. Determines inherited organizational context where explicitly supported.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
