INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('71f348a6-36b8-547d-bf60-7c3d29e4a573', '7179bded-6668-534a-812e-444b66a36d5e', '154416a0-6dbf-599e-b983-8b6f998195b7', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Code', 'Three-letter business currency code, normally an ISO 4217 code where one exists. Used in documents, APIs, integrations, reports, pricing, banking, and accounting. Code identifies the denomination and is not an exchange rate or amount. Provides the currency identity carried through order, invoice, payment, bank, and ledger workflows. Required for interoperable monetary representation. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Currency already uses this value. Up to 3 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
