VALUES ('1d2099d9-3b81-5ce2-8afa-5a90cab9fd50', '2bac6bf6-8667-5a98-8e61-7f4a9a520fbe', '9b572bdc-2583-55e3-8f71-4a8928ae7c4a', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Status', 'Lifecycle state of the exchange-rate record. Used by conversion services to determine whether a rate may be applied. Historical calculations retain the rate record even after it expires. Prevents use of draft, cancelled, or expired rates where policy does not permit them. Required for controlled rate selection. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
