INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ab30326-87b7-5f88-a4e4-3372ea57059b', '7823c815-47fb-5986-a0f0-400da8db6688', '71d10680-d7a1-5c5d-8379-46f5c7de1035', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable system identity of the asset master record. Used to connect maintenance, depreciation, movements, ownership, location, and other lifecycle records to the same physical or accountable asset. assetId identifies the asset itself; assetNumber and serialNumber are business-facing or manufacturer identifiers and must not replace the stable CEDM identity. Every managed asset requires a stable identity so its operational and financial history remains continuous. Must be unique: a save is rejected if another Asset already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9c90b92d-688b-5a4a-b200-f7faaf3a2474', '7823c815-47fb-5986-a0f0-400da8db6688', 'eac19e17-c18c-587a-927f-1968814d8e92', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Asset Number', 'The organization-assigned business identifier used to recognize an asset in operational and financial processes. Used by asset managers, maintenance teams, finance, warehouse operations, reports, documents, and users when referring to the asset. It is the organization''s business reference, while serialNumber may identify the manufacturer''s physical equipment identity and assetId remains the immutable CEDM identity. Required because managed assets need a recognizable organizational identifier. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Asset already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3ac019d8-99e6-5d30-b363-75089ff0e096', '7823c815-47fb-5986-a0f0-400da8db6688', '083e024e-edfd-5201-9f07-6001333b6290', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Name', 'A human-readable description of the asset used to identify it in lists, forms, reports, and operational communication. Supports search, maintenance screens, asset registers, reporting, and user recognition when an asset number alone is insufficient. The name describes this asset instance and should not be confused with Product.name, which describes a reusable product definition or asset type. Required for practical human interpretation of the asset record. Required — the record cannot be saved while this is empty. Up to 300 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('808e3f2b-4bbb-589c-ab08-84fa4b613415', '7823c815-47fb-5986-a0f0-400da8db6688', 'ad0e780f-99a6-5137-8541-11949aa676bb', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Asset Type', 'Classifies the kind of durable resource represented by the asset, such as container, vehicle, machine, building equipment, or other capital-controlled resource. Drives asset policies, maintenance programs, depreciation treatment, reporting, authorization, and lifecycle rules. assetType classifies the asset instance; Product can provide the standardized model or product definition from which the asset originated. Required because asset lifecycle and financial treatment depend on the type of resource being managed. Required — the record cannot be saved while this is empty. Up to 100 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
