-- --------------------------------------------------------------------------
-- Maintenance Plan (bus_maintenance_plan)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('268f733f-059c-58f5-95a0-baf3873d9acf', 'Maintenance Plan', 'Maintain Maintenance Plan records', 'Create, find and maintain Maintenance Plan records. The list shows every Maintenance Plan you have access to — select a row to open it, or use New to add one. Each row is a single Maintenance Plan, described by 7 fields.

Id and Code are unique: no two Maintenance Plan records may share the same value, and a save that would duplicate one is rejected. Code, Name, Maintenance Type and Status must be filled in before the record can be saved.

Asset, Maintenance Work Order and Product refer back to Maintenance Plan, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Maintenance Plan then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Maintenance Plan with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('39bd59db-7196-5c04-a974-242280bc7f6d', 'bus_maintenance_plan', 'Maintenance Plan', 'Represents a maintenance definition called MaintenancePlan within the CEDM business model. MaintenancePlan is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate MaintenancePlan records. The entity participates in a wider business graph through relationships with Asset, Product. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical MaintenancePlan record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '268f733f-059c-58f5-95a0-baf3873d9acf', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
