-- --------------------------------------------------------------------------
-- Maintenance Work Order (bus_maintenance_work_order)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c2bb1e4-4e93-51b8-ac06-f162cdcf0024', 'Maintenance Work Order', 'Maintain Maintenance Work Order records', 'Create, find and maintain Maintenance Work Order records. The list shows every Maintenance Work Order you have access to — select a row to open it, or use New to add one. Each row is a single Maintenance Work Order, described by 15 fields.

Id and Work Order Number are unique: no two Maintenance Work Order records may share the same value, and a save that would duplicate one is rejected. Work Order Number, Work Type, Status, Priority and Requested At must be filled in before the record can be saved.

Every Maintenance Work Order points at Asset, Maintenance Plan, Location, Repair Estimate and Spare Part. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Maintenance Work Order then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Maintenance Work Order with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41548cf5-95ce-532e-8982-badd934e3acb', 'bus_maintenance_work_order', 'Maintenance Work Order', 'Represents one controlled maintenance intervention from reported need through planning, assignment, execution, and completion or cancellation. MaintenanceWorkOrder is the executable maintenance record that turns an identified need into accountable work. It provides the bridge between Asset condition or maintenance policy and the technicians, contractors, parts, estimates, costs, physical movements, and completion evidence needed to restore or preserve asset capability. Used by maintenance management, field service, depot repair, fleet maintenance, facilities management, manufacturing maintenance, container repair, utilities, aviation, automotive, and other asset-intensive operations. Asset identifies what requires work. MaintenancePlan explains recurring preventive work. Party identifies who is responsible. Location identifies where work occurs. RepairEstimate can define expected repair economics before execution. ContainerMovement records physical repositioning when the maintained asset is a container. Detailed labor, parts, inspections, failures, and costs should be represented by their own related entities when required. A request opens the maintenance need. Planning establishes timing and resources. Assignment establishes accountability. In-progress records active execution. On-hold preserves the work order while a blocking condition is resolved. Completion records acceptance of the defined scope. Cancellation terminates the work without claiming that the maintenance objective was achieved. For a container repair, an approved RepairEstimate with disposition REPAIR may create the MaintenanceWorkOrder. If the container is not already at the repair location, ContainerMovement moves it into the workshop or repair area. Work execution then consumes labor/material resources and produces completion evidence. After acceptance, a subsequent operational workflow may return the container to ACTIVE service and move it to an available YardSlot. None of these downstream facts should be inferred solely from work-order status. A shipping container is found with damaged flooring during depot inspection. A corrective MaintenanceWorkOrder identifies the container asset, records the requested condition, receives high priority, links to an approved RepairEstimate for expected material and labor, is assigned to a repair team, may link to ContainerMovement events bringing the container into and out of the workshop, progresses through execution, and is completed after the repair is inspected and accepted.', 'A', FALSE, FALSE, FALSE, TRUE, '7c2bb1e4-4e93-51b8-ac06-f162cdcf0024', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1dbd87c7-c061-5262-9d33-1e8b02465f8b', '7c2bb1e4-4e93-51b8-ac06-f162cdcf0024', '41548cf5-95ce-532e-8982-badd934e3acb', 'Maintenance Work Order', 'Shows one Maintenance Work Order at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Asset, Maintenance Plan, Location, Repair Estimate and Spare Part are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bfc3d5bc-e9ab-5b35-bdf0-5afb327f6462', '41548cf5-95ce-532e-8982-badd934e3acb', 'id', 'Id', 'The immutable system identity of the maintenance work order. Used for maintenance history, integrations, audit, reporting, scheduling, and traceability across the asset lifecycle. Identifies the work order independently of its business number, Asset, MaintenancePlan, assignee, or RepairEstimate. Required because every maintenance intervention must be uniquely traceable.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7ad734c7-61ca-5c80-b22c-20ca25d7c9fb', '41548cf5-95ce-532e-8982-badd934e3acb', 'work_order_number', 'Work Order Number', 'The human-facing reference used by maintenance personnel to identify the work order. Used on maintenance requests, work instructions, technician communications, inspection records, repair documents, and reports. It is a business reference rather than the technical identity and remains the primary operational reference for people. Required so maintenance teams can unambiguously refer to the work instruction.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('840511bb-80de-5279-9067-455e7540cf16', '41548cf5-95ce-532e-8982-badd934e3acb', 'work_type', 'Work Type', 'Classifies the maintenance purpose and determines the general execution method and planning context. Drives maintenance planning, technician assignment, priority, preventive-compliance reporting, repair analytics, and cost analysis. Work type describes why maintenance is being performed; Asset identifies what is being maintained and MaintenancePlan explains recurring planned work when applicable. Examination performed to determine condition, compliance, or the need for further work without necessarily changing the asset. Planned maintenance performed at a defined interval, usage threshold, or condition trigger to reduce the likelihood of failure. Work performed to correct a known condition or restore an asset to its required operating state. Work specifically focused on restoring damaged, defective, or failed components or equipment. Urgent intervention required because an immediate failure, safety concern, operational disruption, or critical condition requires action. Required because maintenance planning and reporting depend on the reason for the work.', 1014, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c0278dbd-40f3-58ea-a7e9-c9d741a0eaa0', '41548cf5-95ce-532e-8982-badd934e3acb', 'status', 'Status', 'The controlled lifecycle state of the maintenance work order. Controls scheduling, assignment, execution, escalation, completion, reporting, and downstream asset-history processing. Work-order status describes the maintenance instruction and execution; it does not by itself prove that an Asset is operational, repaired, or returned to service. A valid maintenance need exists but execution has not yet been fully planned. Timing, scope, or resources have been planned sufficiently for execution. Responsibility for performing the work has been allocated to a Party or maintenance team. Maintenance execution has started. Work is temporarily stopped because of parts, access, safety, approval, diagnosis, scheduling, or another blocking condition. The defined work has been performed and accepted according to the applicable completion criteria. The work order has been intentionally terminated without completing the planned work. Required because maintenance processes must know whether work is pending, active, blocked, completed, or terminated.', 1013, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07a852da-3149-55c9-a081-26ff0c54182d', '41548cf5-95ce-532e-8982-badd934e3acb', 'priority', 'Priority', 'Indicates the operational urgency with which the maintenance work should be scheduled and executed. Used for dispatching, queue ordering, escalation, resource allocation, service-level monitoring, and maintenance planning. Priority expresses urgency; it is different from workType, which expresses purpose, and from Asset criticality, which expresses the importance of the asset itself. Can normally be scheduled after higher-priority maintenance without significant operational impact. Standard maintenance urgency under normal operational planning. Requires accelerated scheduling because delay may materially affect operations, reliability, or service. Requires immediate or near-immediate attention because delay may create severe safety, operational, financial, or regulatory consequences. Required because maintenance queues need a defined prioritization basis.', 1012, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e7a62ce-1548-5909-bedf-9579a875c703', '41548cf5-95ce-532e-8982-badd934e3acb', 'requested_at', 'Requested At', 'The date and time when the maintenance need or work request was formally raised. Used for response-time measurement, backlog analysis, SLA monitoring, maintenance history, and audit. It marks demand for maintenance, not necessarily the time work was scheduled, assigned, or started. Required to measure the elapsed time from maintenance demand to execution.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ad22e98-9c10-5a29-91ad-d037c8bb8278', '41548cf5-95ce-532e-8982-badd934e3acb', 'scheduled_at', 'Scheduled At', 'The planned date and time at which maintenance execution is expected to begin. Used for technician scheduling, asset availability planning, shutdown coordination, parts readiness, and maintenance calendars. It represents a plan and may differ from the actual execution start recorded elsewhere or inferred from status history. Optional while the work remains unscheduled.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('32ecacf5-c22b-5ada-a1eb-faeafbd02c34', '41548cf5-95ce-532e-8982-badd934e3acb', 'completed_at', 'Completed At', 'The date and time at which the maintenance work order was formally completed and accepted. Used for maintenance history, downtime analysis, SLA measurement, compliance reporting, asset availability, and cost closure. Completion means the work-order scope has been accepted; it does not necessarily mean the Asset has returned to service if a separate commissioning or release process exists. Optional until the work is completed.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e992c0ca-f0a4-5d05-b4cc-8a5a12c99224', '41548cf5-95ce-532e-8982-badd934e3acb', 'description', 'Description', 'The human-readable statement of the maintenance problem, requested work, observed condition, or intended scope. Provides context to planners, technicians, inspectors, approvers, and downstream reports when structured fields alone cannot capture the maintenance requirement. It complements structured workType, Asset, RepairEstimate, and MaintenancePlan information and should not be used as the sole source for critical machine-readable conditions. Optional when the work scope is fully defined through structured request or task data.', 10, 4000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('26481614-41d3-53ff-b0f9-2c9da115d41f', '41548cf5-95ce-532e-8982-badd934e3acb', 'asset_id', 'Asset', 'Identifies the physical or operational Asset that the maintenance work is intended to inspect, maintain, correct, or repair. Connects maintenance history to asset condition, service intervals, failure history, warranty, depreciation, and operational availability. Zero or one Asset may be recorded when the work concerns a location, general maintenance activity, or an asset not yet identified at request time. Asset answers what is being maintained; MaintenanceWorkOrder answers what work is being requested or performed on it.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('234a9e9a-1c0b-556d-900c-95a9169de07d', '41548cf5-95ce-532e-8982-badd934e3acb', 'maintenance_plan_id', 'Maintenance Plan', 'Identifies the recurring or preventive maintenance plan that generated or governs the work order. Supports preventive scheduling, compliance tracking, service intervals, and automatic work-order generation. Zero or one plan may be linked because corrective, emergency, and ad-hoc work can originate outside a maintenance plan. MaintenancePlan defines recurring maintenance policy; the work order represents one executable occurrence of that policy.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2a3e655b-8d2a-5be7-999c-81ac1fc8c53d', '41548cf5-95ce-532e-8982-badd934e3acb', 'assignee_id', 'Assignee', 'Identifies the person, team, contractor, or organization responsible for executing or coordinating the work. Drives dispatching, accountability, workload planning, technician performance, contractor management, and communication. Zero or one Party may be assigned while work is unallocated or when assignment is maintained in an external workforce system. Party supplies identity; its applicable role determines whether it acts as technician, maintenance organization, contractor, or another responsibility type.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a95a577f-ea4b-5844-8b84-5b825de1153a', '41548cf5-95ce-532e-8982-badd934e3acb', 'location_id', 'Location', 'Identifies the physical location where the maintenance activity is expected to occur. Used for technician routing, access planning, site coordination, safety requirements, and operational scheduling. Zero or one location may be supplied when the Asset itself determines location or work is performed remotely. Location describes where work occurs and is distinct from the Asset being serviced.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ba70a60d-c54e-5c70-8822-762fedd48dae', '41548cf5-95ce-532e-8982-badd934e3acb', 'repair_estimate_id', 'Repair Estimate', 'Links the work order to the approved estimate that authorizes or informs the repair scope and financial boundary. Supports traceability from condition assessment and approved repair economics into executable maintenance work. Zero or one estimate may be linked because inspection, preventive, corrective, and emergency work may not require a repair estimate. RepairEstimate evaluates and authorizes the proposed repair decision; MaintenanceWorkOrder executes it. A work order must not be treated as proof that the estimate''s predicted amount became actual cost.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e9e2be2-c644-5ea0-a6cb-cea43fc19169', '41548cf5-95ce-532e-8982-badd934e3acb', 'spare_part_id', 'Spare Part', 'The SparePart this MaintenanceWorkOrder belongs to.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
