VALUES ('d11c2931-5b17-5163-8bbd-1efd86cd8173', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'bfc3d5bc-e9ab-5b35-bdf0-5afb327f6462', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable system identity of the maintenance work order. Used for maintenance history, integrations, audit, reporting, scheduling, and traceability across the asset lifecycle. Identifies the work order independently of its business number, Asset, MaintenancePlan, assignee, or RepairEstimate. Required because every maintenance intervention must be uniquely traceable. Must be unique: a save is rejected if another Maintenance Work Order already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
