INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('210a5c46-de41-57a1-a78a-cc8145bbbc99', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '7ad734c7-61ca-5c80-b22c-20ca25d7c9fb', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Work Order Number', 'The human-facing reference used by maintenance personnel to identify the work order. Used on maintenance requests, work instructions, technician communications, inspection records, repair documents, and reports. It is a business reference rather than the technical identity and remains the primary operational reference for people. Required so maintenance teams can unambiguously refer to the work instruction. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Maintenance Work Order already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
