VALUES ('eb4840f5-b8b5-5e28-828b-dfd1d80f2af4', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'e992c0ca-f0a4-5d05-b4cc-8a5a12c99224', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Description', 'The human-readable statement of the maintenance problem, requested work, observed condition, or intended scope. Provides context to planners, technicians, inspectors, approvers, and downstream reports when structured fields alone cannot capture the maintenance requirement. It complements structured workType, Asset, RepairEstimate, and MaintenancePlan information and should not be used as the sole source for critical machine-readable conditions. Optional when the work scope is fully defined through structured request or task data. Up to 4000 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('49cbbde8-1960-5443-9377-aa154a673bea', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '26481614-41d3-53ff-b0f9-2c9da115d41f', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Asset', 'Identifies the physical or operational Asset that the maintenance work is intended to inspect, maintain, correct, or repair. Connects maintenance history to asset condition, service intervals, failure history, warranty, depreciation, and operational availability. Zero or one Asset may be recorded when the work concerns a location, general maintenance activity, or an asset not yet identified at request time. Asset answers what is being maintained; MaintenanceWorkOrder answers what work is being requested or performed on it.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ae853404-ee21-526a-9baf-605ff2a4a2e2', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '234a9e9a-1c0b-556d-900c-95a9169de07d', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Maintenance Plan', 'Identifies the recurring or preventive maintenance plan that generated or governs the work order. Supports preventive scheduling, compliance tracking, service intervals, and automatic work-order generation. Zero or one plan may be linked because corrective, emergency, and ad-hoc work can originate outside a maintenance plan. MaintenancePlan defines recurring maintenance policy; the work order represents one executable occurrence of that policy.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c9f8187-ccb0-5f9e-b11b-300de37058bb', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '2a3e655b-8d2a-5be7-999c-81ac1fc8c53d', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Assignee', 'Identifies the person, team, contractor, or organization responsible for executing or coordinating the work. Drives dispatching, accountability, workload planning, technician performance, contractor management, and communication. Zero or one Party may be assigned while work is unallocated or when assignment is maintained in an external workforce system. Party supplies identity; its applicable role determines whether it acts as technician, maintenance organization, contractor, or another responsibility type.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ebe30f4f-8731-595a-b12c-c2a20d6a9998', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'a95a577f-ea4b-5844-8b84-5b825de1153a', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Location', 'Identifies the physical location where the maintenance activity is expected to occur. Used for technician routing, access planning, site coordination, safety requirements, and operational scheduling. Zero or one location may be supplied when the Asset itself determines location or work is performed remotely. Location describes where work occurs and is distinct from the Asset being serviced.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('716895f6-d490-567a-b598-489246711336', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'ba70a60d-c54e-5c70-8822-762fedd48dae', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Repair Estimate', 'Links the work order to the approved estimate that authorizes or informs the repair scope and financial boundary. Supports traceability from condition assessment and approved repair economics into executable maintenance work. Zero or one estimate may be linked because inspection, preventive, corrective, and emergency work may not require a repair estimate. RepairEstimate evaluates and authorizes the proposed repair decision; MaintenanceWorkOrder executes it. A work order must not be treated as proof that the estimate''s predicted amount became actual cost.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('534b6ab4-c30f-50e3-98e0-4e870f3d907a', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '1e9e2be2-c644-5ea0-a6cb-cea43fc19169', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Spare Part', 'The SparePart this MaintenanceWorkOrder belongs to.', 150, 150, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
