-- --------------------------------------------------------------------------
-- Repair Estimate (bus_repair_estimate)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2dccccb8-4d9b-5661-9241-74e63fdb8451', 'Repair Estimate', 'Maintain Repair Estimate records', 'Create, find and maintain Repair Estimate records. The list shows every Repair Estimate you have access to — select a row to open it, or use New to add one. Each row is a single Repair Estimate, described by 12 fields.

Id and Estimate Number are unique: no two Repair Estimate records may share the same value, and a save that would duplicate one is rejected. Estimate Number, Revision, Estimate Date, Status and Container must be filled in before the record can be saved.

Every Repair Estimate points at Currency, Container and Organization. Choose the linked record from the lookup on those fields rather than typing an identifier. Maintenance Work Order and Repair Estimate Line refer back to Repair Estimate, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Repair Estimate then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Repair Estimate with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('96944009-759a-5f30-b8d6-79fbfeef3d44', 'bus_repair_estimate', 'Repair Estimate', 'Represents the controlled decision assessment between asset condition and the eventual repair or commercial disposition action. RepairEstimate is not the repair itself. It evaluates what is wrong, what it is expected to cost, and which outcome is economically or operationally appropriate. It therefore sits between inspection/condition evidence and downstream execution or disposition. Used by depot maintenance, fleet management, repair vendors, asset managers, finance, approval workflows, and predictive analytics. Historical estimates can also provide labeled data for disposition and sale-value prediction. Container identifies the asset. RepairEstimateLine explains technical scope. MaintenanceWorkOrder executes approved repair. SalesOrder or a disposition transaction executes sale. Inventory and financial transactions record actual operational and monetary outcomes. Currency qualifies monetary values and Document supplies evidence. DRAFT → SUBMITTED → APPROVED or REJECTED, followed by COMPLETED or CANCELLED according to policy. Approval authorizes a decision but does not itself perform repair or sale. Revisions preserve decision history rather than overwriting earlier approved facts. When disposition is REPAIR, an approved estimate may create one or more MaintenanceWorkOrders. The work order must reference the originating estimate, remain within the approved scope unless an authorized estimate revision is made, and record actual execution separately. Work-order completion does not automatically make the estimate''s estimated amounts actual costs. A returned container has damaged flooring, side panels, and door hardware. The estimate contains line-level components and labor, compares expected repair cost with sale value and asset economics, and is approved with disposition REPAIR. A MaintenanceWorkOrder is then created for execution. The final actual repair cost is recorded separately from the estimate.', 'A', FALSE, FALSE, FALSE, TRUE, '2dccccb8-4d9b-5661-9241-74e63fdb8451', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('97acf41a-66cb-51ba-862b-5070c5812a13', '2dccccb8-4d9b-5661-9241-74e63fdb8451', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'Repair Estimate', 'Shows one Repair Estimate at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency, Container and Organization are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd94e2c4-7efc-53b6-97e8-f4eef30a30c3', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'id', 'Id', 'The immutable system identity of the repair estimate. Connects the assessment to revisions, line items, approvals, work orders, documents, analytics, and integrations. Identifies the assessment record; Container identifies the asset and RepairEstimateLine identifies its detailed technical scope. Required so the decision and its history remain independently traceable.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('38c0c2ac-2159-576d-95e1-8cdf83644a45', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'estimate_number', 'Estimate Number', 'The human-facing business reference for the repair assessment. Used by depot, maintenance, fleet, owners, approvers, customers, and reports. Unlike repairEstimateId, this is intended for business communication and documents. Required for operational and approval workflows.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('369ef294-3421-5083-9f2b-3f5a4777ff50', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'revision', 'Revision', 'The version number of the technical and commercial assessment. Preserves changes in damage scope, material pricing, labor assumptions, disposition, or approval values. A revision is historical decision context and must not silently overwrite an earlier approved assessment. Required for traceable estimate evolution.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('58aab76a-3162-5ea7-a70e-6f44e3860ed7', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'estimate_date', 'Estimate Date', 'The business date on which this estimate revision was prepared or recognized. Supports approval chronology, estimate aging, repair-cycle analysis, and financial reporting. Distinct from Container manufacture date, damage date, repair completion date, or sale date. Required to establish decision chronology.', 15, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('461b5498-361b-583b-a234-69aff081e7cb', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'status', 'Status', 'The lifecycle state of the assessment and its authorization status. Controls preparation, review, approval, rejection, completion, and cancellation workflows. Estimate status describes the decision artifact; it does not mean that repair execution or sale execution has completed. Assessment is still being prepared. Assessment is awaiting review or authorization. The proposed decision/scope has been authorized; execution remains a separate process. The proposed assessment or decision was not authorized. The estimate''s decision process is concluded. Assessment was intentionally terminated and must not drive active downstream work. Required to separate assessment preparation from authorization and execution.', 1028, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f0f6b296-9b9b-5fdc-b489-9b7e8d96f658', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'disposition', 'Disposition', 'The intended operational or commercial outcome selected after evaluating condition and economics. Determines whether the asset returns to lease-related use, enters a sale process, is scrapped, requires repair, or remains pending. Disposition is a decision about the asset, not a physical repair status. REPAIR may create a MaintenanceWorkOrder; SALE may create a SalesOrder or disposition transaction. Asset is intended to remain available for lease-related use after the applicable process. Asset is intended for commercial sale rather than return to the active lease fleet. Asset is intended for disposal and removal from productive inventory. Repair is justified and maintenance execution is required or expected. No final disposition has been executed; further information or approval is required. Optional until a disposition decision is reached.', 1027, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3b96432f-f16b-554b-873f-2e8ab28c0b23', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'estimated_repair_amount', 'Estimated Repair Amount', 'The estimated cost of the repair scope represented by the assessment. Supports repair-vs-sale-vs-scrap economics, approval thresholds, budgets, and predictive analysis. Should reconcile to RepairEstimateLine values and Currency; it is an estimate, not an actual posted maintenance cost. Optional until sufficient repair scope is known.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('282c7a24-cb1b-56df-826b-dade37eab869', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'estimated_sale_amount', 'Estimated Sale Amount', 'The expected realization from selling the asset under the current valuation assumptions. Supports disposition economics and comparison with repair cost, book value, residual value, and lease alternatives. It is decision-support data, not an executed sale amount or payment. Optional when sale is not under consideration.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('38d89dd7-4fc6-5a32-a8a6-7a3ec38d127e', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'approved_amount', 'Approved Amount', 'The monetary amount explicitly authorized by the approval decision. Establishes the financial boundary for downstream repair execution or approved disposition activity. Approval amount is not the same as final actual maintenance cost; actual cost belongs to execution and financial records. Optional before approval or for non-monetary decisions.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f6b571cd-61d2-5964-acaa-28fa635aa5fb', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'currency_id', 'Currency', 'The currency that gives monetary estimate values their denomination. Required to interpret repair, sale, and approval amounts consistently. Currency qualifies amounts; it does not identify ownership, supplier, or asset identity. Optional while monetary assessment is incomplete.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2e8050d0-96f9-5861-9d92-4b0bc1c1a7ae', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'container_id', 'Container', 'The physical container whose condition, repair economics, and disposition are being assessed. Connects the estimate to equipment identity, current location, ownership/lease context, condition, and maintenance history. Exactly one Container is assessed. Container is the asset; RepairEstimate records a decision assessment about that asset without duplicating master data.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc13b57b-cead-561a-a02f-690477184101', '96944009-759a-5f30-b8d6-79fbfeef3d44', 'organization_id', 'Organization', 'The organization responsible for preparing, owning, or approving the assessment. Supports depot responsibility, approval authority, cost attribution, and reporting. Optional when organization is inherited from operating context. This organization may differ from Container owner, lessor, lessee, customer, or repair vendor.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8c4e79e4-a8f5-55c3-8f57-b1aabee67bf8', '97acf41a-66cb-51ba-862b-5070c5812a13', 'fd94e2c4-7efc-53b6-97e8-f4eef30a30c3', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable system identity of the repair estimate. Connects the assessment to revisions, line items, approvals, work orders, documents, analytics, and integrations. Identifies the assessment record; Container identifies the asset and RepairEstimateLine identifies its detailed technical scope. Required so the decision and its history remain independently traceable. Must be unique: a save is rejected if another Repair Estimate already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e96ac4c3-4fcb-5ec9-9d6e-40492e6c6292', '97acf41a-66cb-51ba-862b-5070c5812a13', '38c0c2ac-2159-576d-95e1-8cdf83644a45', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Estimate Number', 'The human-facing business reference for the repair assessment. Used by depot, maintenance, fleet, owners, approvers, customers, and reports. Unlike repairEstimateId, this is intended for business communication and documents. Required for operational and approval workflows. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Repair Estimate already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('209f3e3e-10db-5459-a538-9c29e91c9009', '97acf41a-66cb-51ba-862b-5070c5812a13', '369ef294-3421-5083-9f2b-3f5a4777ff50', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Revision', 'The version number of the technical and commercial assessment. Preserves changes in damage scope, material pricing, labor assumptions, disposition, or approval values. A revision is historical decision context and must not silently overwrite an earlier approved assessment. Required for traceable estimate evolution. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6b221079-2a37-5f95-9621-a4d0715cf272', '97acf41a-66cb-51ba-862b-5070c5812a13', '58aab76a-3162-5ea7-a70e-6f44e3860ed7', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Estimate Date', 'The business date on which this estimate revision was prepared or recognized. Supports approval chronology, estimate aging, repair-cycle analysis, and financial reporting. Distinct from Container manufacture date, damage date, repair completion date, or sale date. Required to establish decision chronology. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e7bd7357-213b-5a52-890e-515a48350c80', '97acf41a-66cb-51ba-862b-5070c5812a13', '461b5498-361b-583b-a234-69aff081e7cb', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Status', 'The lifecycle state of the assessment and its authorization status. Controls preparation, review, approval, rejection, completion, and cancellation workflows. Estimate status describes the decision artifact; it does not mean that repair execution or sale execution has completed. Assessment is still being prepared. Assessment is awaiting review or authorization. The proposed decision/scope has been authorized; execution remains a separate process. The proposed assessment or decision was not authorized. The estimate''s decision process is concluded. Assessment was intentionally terminated and must not drive active downstream work. Required to separate assessment preparation from authorization and execution. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9df1f430-86b3-5a7e-8d52-e2f4ed8853da', '97acf41a-66cb-51ba-862b-5070c5812a13', 'f0f6b296-9b9b-5fdc-b489-9b7e8d96f658', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Disposition', 'The intended operational or commercial outcome selected after evaluating condition and economics. Determines whether the asset returns to lease-related use, enters a sale process, is scrapped, requires repair, or remains pending. Disposition is a decision about the asset, not a physical repair status. REPAIR may create a MaintenanceWorkOrder; SALE may create a SalesOrder or disposition transaction. Asset is intended to remain available for lease-related use after the applicable process. Asset is intended for commercial sale rather than return to the active lease fleet. Asset is intended for disposal and removal from productive inventory. Repair is justified and maintenance execution is required or expected. No final disposition has been executed; further information or approval is required. Optional until a disposition decision is reached.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e5d4cc08-c10c-5192-854d-74b4538263f0', '97acf41a-66cb-51ba-862b-5070c5812a13', '3b96432f-f16b-554b-873f-2e8ab28c0b23', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Estimated Repair Amount', 'The estimated cost of the repair scope represented by the assessment. Supports repair-vs-sale-vs-scrap economics, approval thresholds, budgets, and predictive analysis. Should reconcile to RepairEstimateLine values and Currency; it is an estimate, not an actual posted maintenance cost. Optional until sufficient repair scope is known.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8301c40c-22ed-5e1f-b5c4-802d1f98474f', '97acf41a-66cb-51ba-862b-5070c5812a13', '282c7a24-cb1b-56df-826b-dade37eab869', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Estimated Sale Amount', 'The expected realization from selling the asset under the current valuation assumptions. Supports disposition economics and comparison with repair cost, book value, residual value, and lease alternatives. It is decision-support data, not an executed sale amount or payment. Optional when sale is not under consideration.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4735697e-7d1c-58a7-82f2-d3f6f8cbf1ff', '97acf41a-66cb-51ba-862b-5070c5812a13', '38d89dd7-4fc6-5a32-a8a6-7a3ec38d127e', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Approved Amount', 'The monetary amount explicitly authorized by the approval decision. Establishes the financial boundary for downstream repair execution or approved disposition activity. Approval amount is not the same as final actual maintenance cost; actual cost belongs to execution and financial records. Optional before approval or for non-monetary decisions.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0dbf4163-1dc6-5c59-adfd-3c2f35241a9d', '97acf41a-66cb-51ba-862b-5070c5812a13', 'f6b571cd-61d2-5964-acaa-28fa635aa5fb', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Currency', 'The currency that gives monetary estimate values their denomination. Required to interpret repair, sale, and approval amounts consistently. Currency qualifies amounts; it does not identify ownership, supplier, or asset identity. Optional while monetary assessment is incomplete.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5550db99-92d7-5b38-a538-13d094641aea', '97acf41a-66cb-51ba-862b-5070c5812a13', '2e8050d0-96f9-5861-9d92-4b0bc1c1a7ae', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Container', 'The physical container whose condition, repair economics, and disposition are being assessed. Connects the estimate to equipment identity, current location, ownership/lease context, condition, and maintenance history. Exactly one Container is assessed. Container is the asset; RepairEstimate records a decision assessment about that asset without duplicating master data. Required — the record cannot be saved while this is empty.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c54c855d-3046-58ba-af9e-9e62f0b69c8c', '97acf41a-66cb-51ba-862b-5070c5812a13', 'cc13b57b-cead-561a-a02f-690477184101', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Organization', 'The organization responsible for preparing, owning, or approving the assessment. Supports depot responsibility, approval authority, cost attribution, and reporting. Optional when organization is inherited from operating context. This organization may differ from Container owner, lessor, lessee, customer, or repair vendor.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
