-- --------------------------------------------------------------------------
-- Equipment (bus_equipment)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('70975225-4566-5f16-b1cd-b518b7317acb', 'Equipment', 'Maintain Equipment records', 'Create, find and maintain Equipment records. The list shows every Equipment you have access to — select a row to open it, or use New to add one. Each row is a single Equipment, described by 4 fields.

Id is unique: no two Equipment records may share the same value, and a save that would duplicate one is rejected.

Every Equipment points at Asset and Spare Part. Choose the linked record from the lookup on those fields rather than typing an identifier. Failure refers back to Equipment, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Equipment then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Equipment with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4fe3f064-ce78-5045-b5ed-fa29ede187d5', 'bus_equipment', 'Equipment', 'A governed maintainable equipment identity linked to an Asset where financial capitalization and operational maintenance identities overlap. Provide canonical enterprise semantics for Equipment. A governed maintainable equipment identity linked to an Asset where financial capitalization and operational maintenance identities overlap. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, '70975225-4566-5f16-b1cd-b518b7317acb', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('68e47bd1-382b-5769-8204-8991c68ffcee', '70975225-4566-5f16-b1cd-b518b7317acb', '4fe3f064-ce78-5045-b5ed-fa29ede187d5', 'Equipment', 'Shows one Equipment at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Asset and Spare Part are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
