VALUES ('f83c70b5-f816-5397-a02d-ea085dd56c73', '4fe3f064-ce78-5045-b5ed-fa29ede187d5', 'id', 'Id', 'Stable identity of Equipment. Identifies one governed Equipment record independently of mutable state. Operations, finance, integration, reporting and audit. Referenced by compatible lifecycle and transaction records. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
