VALUES ('413491d2-790a-57b3-af16-4f48f6d63139', '4fe3f064-ce78-5045-b5ed-fa29ede187d5', 'asset_id', 'Asset', 'Financial/fixed Asset represented by equipment. Connects maintainable object to capitalization identity when applicable. EAM, depreciation and maintenance. Optional for non-capitalized equipment. Maintenance history remains independent from accounting postings.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
