INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7045b79f-d72f-5f16-9fc8-3113fe0a2986', 'Failure', 'Maintain Failure records', 'Create, find and maintain Failure records. The list shows every Failure you have access to — select a row to open it, or use New to add one. Each row is a single Failure, described by 3 fields.

Id is unique: no two Failure records may share the same value, and a save that would duplicate one is rejected. Equipment must be filled in before the record can be saved.

Every Failure points at Equipment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Failure then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Failure with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('16369de7-6cef-528b-8ae9-33a8bd35f4a9', 'bus_failure', 'Failure', 'A governed observed equipment or asset failure recording symptom, occurrence, effect, and maintenance context without overwriting repair evidence. Provide canonical enterprise semantics for Failure. A governed observed equipment or asset failure recording symptom, occurrence, effect, and maintenance context without overwriting repair evidence. Used in asset, maintenance, treasury, banking, credit-risk, accounting, integration, and audit workflows where applicable. Connects operational or financial lifecycle evidence to canonical masters while keeping accounting, bank, and physical records authoritative in their own domains. Created under governed conditions, progressed or finalized with audit history, and corrected through explicit subsequent evidence. Asset lifecycle, maintenance, treasury operations, bank reconciliation, lending, accounting, reporting, and audit. Enterprise fixed assets, equipment reliability, bank close, FX, deposits, interest, and secured lending.', 'A', FALSE, FALSE, FALSE, TRUE, '7045b79f-d72f-5f16-9fc8-3113fe0a2986', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
