-- Spare Part (bus_spare_part)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7d22f6ed-72f8-51ba-8b77-efc14e5ba107', 'Spare Part', 'Maintain Spare Part records', 'Create, find and maintain Spare Part records. The list shows every Spare Part you have access to — select a row to open it, or use New to add one. Each row is a single Spare Part, described by 3 fields.

Id is unique: no two Spare Part records may share the same value, and a save that would duplicate one is rejected. Criticality and Product must be filled in before the record can be saved.

Every Spare Part points at Product. Choose the linked record from the lookup on those fields rather than typing an identifier. Maintenance Work Order and Equipment refer back to Spare Part, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Spare Part then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Spare Part with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('748ec4fc-7dce-5327-8cef-c5cae24b68ed', 'bus_spare_part', 'Spare Part', 'Maintenance-specific role for an inventory Product used to repair or service assets and equipment. Connect maintenance planning and execution to canonical product and inventory semantics without creating a second material master. A SparePart states that a Product is approved or expected for maintenance use. Used for preventive/corrective maintenance planning, work-order materials, critical-spares stocking, procurement and maintenance costing. Product provides material identity; Equipment provides applicability; MaintenanceWorkOrder provides demand/execution; InventoryMovement provides physical stock truth. Approved for maintenance use, maintained for applicability and criticality, then retired without rewriting historical work orders. Maintenance planning, spare-parts management, reservation, issue, return, replenishment and reliability analysis. Bearings, filters, seals, replacement motors and repair kits.', 'A', FALSE, FALSE, FALSE, TRUE, '7d22f6ed-72f8-51ba-8b77-efc14e5ba107', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('92f7bcbb-b2f1-57cd-bb7e-031901bf8e78', '7d22f6ed-72f8-51ba-8b77-efc14e5ba107', '748ec4fc-7dce-5327-8cef-c5cae24b68ed', 'Spare Part', 'Shows one Spare Part at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('753078a4-e9d8-54d1-b8b9-60e17ab01b7d', '748ec4fc-7dce-5327-8cef-c5cae24b68ed', 'id', 'Id', 'Stable spare-part identity. Identifies one governed maintenance-material designation. Maintenance planning, inventory, procurement and costing. References canonical Product rather than duplicating product master data. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
