INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('95f28e68-ae3b-5988-ad03-76ac622229b2', '748ec4fc-7dce-5327-8cef-c5cae24b68ed', 'criticality', 'Criticality', 'Maintenance availability criticality. Indicates operational consequence of part unavailability. Stocking, replenishment and maintenance planning. Does not replace product or asset criticality. Limited operational consequence. Material but manageable consequence. Significant availability consequence. Severe operational/safety/service consequence requiring strict control. Required.', 1029, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
