-- --------------------------------------------------------------------------
-- Repair Estimate Line (bus_repair_estimate_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'bus_repair_estimate_line', 'Repair Estimate Line', 'Represents one actionable or evaluative item within a repair estimate, connecting observed asset condition to proposed repair work and estimated cost. RepairEstimateLine is the detailed evidence behind the overall repair decision. It can identify what is damaged, where it is damaged, what repair is proposed, what material or replacement is required, and what labor and cost are expected. Used by inspectors, repair estimators, maintenance planners, depot operators, repair vendors, procurement, inventory, finance, and predictive analytics. RepairEstimate provides the overall decision and Container context. DamageCode describes the observed condition, ComponentCode identifies the affected area, RepairCode describes the proposed action, and MaterialCode/quantity describe expected material requirements. MaintenanceWorkOrder later converts approved repair scope into executable work; actual material consumption and labor are separate execution outcomes. Lines are created while an estimate is prepared, may be revised as inspection or pricing changes, become part of an approved scope when the parent estimate is approved, and remain historical evidence of the decision even after maintenance execution completes. An inspection finds a damaged container door gasket. A RepairEstimateLine records the damage code, affected component, proposed repair code, replacement material, quantity of one, estimated material cost, estimated labor cost, and total estimated line cost. After approval, the line can be used to create executable maintenance work and material demand.', 'A', FALSE, FALSE, FALSE, TRUE, '2dccccb8-4d9b-5661-9241-74e63fdb8451', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('97359bac-c631-5f60-9315-080dcf3ae376', '2dccccb8-4d9b-5661-9241-74e63fdb8451', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'Repair Estimate Line', 'Shows one Repair Estimate Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Repair Estimate is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f53c267a-10ea-5872-a768-2f257e34882a', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'id', 'Id', 'The immutable system identity of the estimate line. Used for traceability between the estimate, repair execution, material planning, analytics, and integrations. Identifies one detailed estimate item independently of its parent RepairEstimate, line number, damage, component, or material. Required so every estimated repair requirement can be individually traced.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('aa9cd9ac-6a26-50be-9b13-9ae45f3e6448', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'line_number', 'Line Number', 'The sequence number identifying the line within a particular RepairEstimate revision. Used by inspectors, repair estimators, approvers, work-order planners, documents, and reports to discuss a specific estimate item. It is unique within the parent estimate revision rather than globally; the stable identity remains repairEstimateLineId. Required for human-readable estimate structure and traceability.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bc388a40-3c50-5c7b-93c5-3a6d519c5a38', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'repair_code', 'Repair Code', 'A standardized classification identifying the repair operation or repair action proposed for the line. Used for maintenance coding, labor standards, repair analytics, cost estimation, vendor instructions, and historical repair analysis. RepairCode describes the required action, while DamageCode describes the observed condition that caused the action and ComponentCode identifies the affected component. Optional when the repair action is still being assessed or is represented by another controlled classification.', 10, 50, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ae495fd6-63ec-5a31-a1d1-7050a5a41b04', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'damage_code', 'Damage Code', 'A standardized classification identifying the damage or defect observed on the asset. Used for inspection, repair estimation, damage trend analysis, customer recovery, warranty/lease assessment, and predictive maintenance models. DamageCode explains the condition; RepairCode explains the proposed response. Keeping them separate allows the same damage type to lead to different repair or disposition decisions. Optional when no specific damage classification is available or the line represents a non-damage activity such as inspection or routine labor.', 10, 50, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a1648568-41d7-5ac4-9add-9aeb51553543', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'component_code', 'Component Code', 'Identifies the component, structural area, or equipment part affected by the estimated work. Used to locate the work physically, select repair procedures, determine material requirements, analyze recurring failures, and calculate component-level costs. ComponentCode provides the ''where'' or affected part of the repair; DamageCode provides the condition and RepairCode provides the proposed action. Optional when the estimate line applies to the asset generally or the component is not yet identified.', 10, 50, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3d3fd611-3a79-5ee8-acea-7410bc6da141', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'material_code', 'Material Code', 'Identifies a material or replacement item expected to be consumed or installed as part of the repair. Used for material planning, inventory reservation, purchasing, supplier sourcing, costing, and maintenance execution. MaterialCode identifies what is consumed or installed; quantity and materialAmount determine the estimated requirement and financial impact. Optional for labor-only, inspection-only, adjustment, or repair methods that do not require a specific material.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7416b167-554e-5be3-a0b6-b0eb7ac95825', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'quantity', 'Quantity', 'The estimated quantity of the material, replacement item, or measurable repair resource required for this line. Used to calculate material requirements, expected consumption, replacement cost, inventory demand, and repair scope. Quantity must be interpreted with MaterialCode and the applicable UnitOfMeasure; it is an estimate of required work/material, not necessarily actual consumption. Optional for activities where quantity is not meaningful or is represented through labor or fixed-price estimation.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('994b391a-b8b9-5606-aefc-9d843f834a34', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'material_amount', 'Material Amount', 'The estimated cost attributable to materials consumed or installed for this repair line. Used for repair-cost calculation, approval, inventory valuation, supplier comparison, and actual-versus-estimated analysis. MaterialAmount belongs to the estimate and should not be interpreted as the actual inventory issue or supplier invoice amount. Optional when the line has no material component.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b2819216-dee8-5736-b06a-3bca67eff7c7', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'labour_amount', 'Labour Amount', 'The estimated labor cost required to perform the repair activity represented by the line. Used for repair economics, approval thresholds, workforce planning, vendor quotation comparison, and variance analysis. LabourAmount is an estimate of execution cost; actual technician time and actual labor cost belong to maintenance execution records. Optional for material-only or externally priced repair lines.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b4b76911-4830-505d-80df-2779d432a89b', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'replacement_amount', 'Replacement Amount', 'The estimated cost of replacing the affected component or asset element when replacement is the selected repair approach. Used to compare repair versus replacement economics and to support disposition decisions. ReplacementAmount may overlap with material cost depending on the organization''s costing policy, so its relationship to MaterialAmount must be governed by the estimate''s calculation rules. Optional when replacement is not being considered.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a34bb092-14db-5149-a072-78cbcce3815c', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'total_amount', 'Total Amount', 'The estimated total financial impact of the repair requirement represented by this line. Used to aggregate RepairEstimate cost, support approval, compare alternatives, and feed repair/disposition analytics. It should reconcile to the applicable material, labor, replacement, discount, and other cost components according to the organization''s estimate calculation policy. Optional while the line is incomplete or not financially valued.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bdf34601-81b9-54b9-b629-b1674ec06f4a', 'a6c2bd27-0a48-5468-8575-f7fe15ad2c17', 'repair_estimate_id', 'Repair Estimate', 'Identifies the RepairEstimate revision to which this detailed repair requirement belongs. Supplies the container, estimate revision, status, disposition, currency, and approval context for the line. Every RepairEstimateLine belongs to exactly one RepairEstimate. The parent estimate provides decision context; the line provides the technical and cost detail supporting that decision.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
