VALUES ('3e5ac340-9bf6-5d9e-b543-ec111ed33242', '97359bac-c631-5f60-9315-080dcf3ae376', 'b2819216-dee8-5736-b06a-3bca67eff7c7', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Labour Amount', 'The estimated labor cost required to perform the repair activity represented by the line. Used for repair economics, approval thresholds, workforce planning, vendor quotation comparison, and variance analysis. LabourAmount is an estimate of execution cost; actual technician time and actual labor cost belong to maintenance execution records. Optional for material-only or externally priced repair lines.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ea4d13ad-557c-557f-af9d-033ad6ddacf5', '97359bac-c631-5f60-9315-080dcf3ae376', 'b4b76911-4830-505d-80df-2779d432a89b', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Replacement Amount', 'The estimated cost of replacing the affected component or asset element when replacement is the selected repair approach. Used to compare repair versus replacement economics and to support disposition decisions. ReplacementAmount may overlap with material cost depending on the organization''s costing policy, so its relationship to MaterialAmount must be governed by the estimate''s calculation rules. Optional when replacement is not being considered.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('781532a9-cca0-5738-8e7c-ca76efabbbc6', '97359bac-c631-5f60-9315-080dcf3ae376', 'a34bb092-14db-5149-a072-78cbcce3815c', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Total Amount', 'The estimated total financial impact of the repair requirement represented by this line. Used to aggregate RepairEstimate cost, support approval, compare alternatives, and feed repair/disposition analytics. It should reconcile to the applicable material, labor, replacement, discount, and other cost components according to the organization''s estimate calculation policy. Optional while the line is incomplete or not financially valued.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d993883a-3b5e-5277-8409-34f299c824fe', '97359bac-c631-5f60-9315-080dcf3ae376', 'bdf34601-81b9-54b9-b629-b1674ec06f4a', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Repair Estimate', 'Identifies the RepairEstimate revision to which this detailed repair requirement belongs. Supplies the container, estimate revision, status, disposition, currency, and approval context for the line. Every RepairEstimateLine belongs to exactly one RepairEstimate. The parent estimate provides decision context; the line provides the technical and cost detail supporting that decision. Required — the record cannot be saved while this is empty.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
